import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s1 = sc.nextLine();
            if (sc.hasNextLine()) {
                String s2 = sc.nextLine();
                System.out.println(s2 + "\n" + s1);
            }
        }
    }
}

